={
  "model": "openai/gpt-oss-120b",
  "temperature": 0,
  "response_format": { "type": "json_object" },
  "messages": [
    { "role": "system", "content": "Turn this recruiter question into search filters. Never name candidates. Skill names must match the CV database: GHL (for GoHighLevel), Make.com, QuickBooks Online, Keap, Google Workspace, Microsoft 365, Canva, TikTok Ads (paid ads only), TikTok (organic); any other tool as written. Every tool, skill or task the question asks for (for example travel booking, calendar management or Shopify) goes in must_skills, with years of it in min_years. Use nice_skills only for things the question calls optional, a plus or preferred. Years of a profession (bookkeeping, customer support, social media, assistant work) go in min_role_years. Certifications go in must_certifications, for example QuickBooks ProAdvisor or CPA. If the question asks for someone who worked directly for a CEO or founder, put supported_ceo in must_flags. Set role only when the question names a profession: ghl_automation, executive_assistant, bookkeeper, social_media, customer_support; otherwise null. Return only JSON in this shape: {\"role\":null,\"must_skills\":[{\"name\":\"\",\"min_years\":0}],\"must_languages\":[],\"must_certifications\":[],\"must_flags\":[],\"min_role_years\":0,\"nice_skills\":[]}" },
    { "role": "user", "content": {{ JSON.stringify($json.question) }} }
  ]
}

parameters.jsCode:
const r = JSON.parse($json.choices[0].message.content);
const arr = v => Array.isArray(v) ? v.filter(Boolean) : [];
const roles = ['ghl_automation', 'executive_assistant', 'bookkeeper', 'social_media', 'customer_support'];
return [{ json: {
  role: roles.includes(r.role) ? r.role : null,
  must_skills: arr(r.must_skills).filter(s => s.name),
  must_languages: arr(r.must_languages),
  must_certifications: arr(r.must_certifications),
  must_flags: arr(r.must_flags).filter(x => x === 'supported_ceo'),
  min_role_years: Number(r.min_role_years) || 0,
  nice_skills: arr(r.nice_skills),
} }];

const f = $('Parse Filters').first().json;
const ALIAS = { 'gohighlevel': 'ghl', 'go high level': 'ghl', 'highlevel': 'ghl', 'make': 'make.com',
  'integromat': 'make.com', 'make (integromat)': 'make.com', 'integromat / make': 'make.com',
  'qbo': 'quickbooks online', 'quickbooks online (qbo)': 'quickbooks online', 'keap (infusionsoft)': 'keap',
  'infusionsoft': 'keap', 'g suite': 'google workspace', 'gsuite': 'google workspace',
  'ms office 365': 'microsoft 365', 'canva pro': 'canva', 'tiktok ads manager': 'tiktok ads' };
const canon = s => { const k = String(s || '').toLowerCase().trim(); return ALIAS[k] || k; };
const prof = c => { try { return typeof c.profile === 'string' ? JSON.parse(c.profile) : (c.profile || {}); } catch (e) { return {}; } };
const findSkill = (p, n) => (p.skills || []).find(x => canon(x.name) === canon(n));
const speaks = (p, l) => (p.languages || []).some(x => canon(x.name) === canon(l));
const hasCert = (p, c) => {
  const b = canon(c);
  return !!b && (p.certifications || []).some(x => { const a = canon(x); return a && (a.includes(b) || b.includes(a)); });
};

const asked = f.must_skills.length + f.must_languages.length + f.must_certifications.length
  + f.must_flags.length + (f.min_role_years > 0 ? 1 : 0);
if (!asked) return [{ json: { filters: f, matches: [] } }];

const now = Date.now();
const matches = $('Get Candidates').all().map(i => i.json)
  .filter(c => c.id && c.active_cv_file)
  .map(c => ({ c, p: prof(c) }))
  .filter(({ p }) =>
    (!f.role || p.role_category === f.role) &&
    (p.role_years || 0) >= f.min_role_years &&
    f.must_skills.every(s => {
      const m = findSkill(p, s.name);
      return m && (m.years ?? p.role_years ?? 0) >= (s.min_years || 0);
    }) &&
    f.must_languages.every(l => speaks(p, l)) &&
    f.must_certifications.every(x => hasCert(p, x)) &&
    f.must_flags.every(x => (p.flags || []).includes(x)))
  .map(({ c, p }) => {
    const nice = f.nice_skills.length ? f.nice_skills.filter(n => findSkill(p, n)).length / f.nice_skills.length : 1;
    const recent = p.cv_date && (now - Date.parse(p.cv_date)) <= 730 * 864e5 ? 1 : 0;
    return { id: c.id, full_name: c.full_name, email: c.email, cv_text: c.cv_text,
             active_cv_file: c.active_cv_file, score: Math.round(70 + 20 * nice + 10 * recent) };
  })
  .sort((a, b) => b.score - a.score || a.full_name.localeCompare(b.full_name)).slice(0, 5);
return [{ json: { filters: f, matches } }];

