const needs = f => [
  ...(f.role ? [f.role.replace(/_/g, ' ')] : []),
  ...f.must_skills.map(s => s.min_years ? `${s.min_years}+ yrs ${s.name}` : s.name),
  ...f.must_languages,
  ...f.must_certifications,
  ...(f.must_flags.includes('supported_ceo') ? ['worked for a CEO or founder'] : []),
  ...(f.min_role_years ? [`${f.min_role_years}+ years in the role`] : []),
];

// Every candidate comes from the database. The AI only words the reason; its quote must really be in the CV,
// otherwise a plain reason built from the filters is used instead.
const q = $('When Executed by Another Workflow').first().json.question;
const { filters: f, matches } = $('Score').first().json;
const norm = s => String(s || '').toLowerCase()
  .replace(/[‘’]/g, "'").replace(/[“”]/g, '"').replace(/[‐-―]/g, '-')
  .replace(/\s+/g, ' ').trim();
const reasons = $input.all();
const out = matches.map((c, i) => {
  let r = {};
  try { r = JSON.parse(reasons[i].json.choices[0].message.content); } catch (e) {}
  const ok = r.quote && r.line1 && norm(c.cv_text).includes(norm(r.quote));
  return { id: c.id, name: c.full_name, email: c.email, score: c.score, cv_file: c.active_cv_file,
    line1: ok ? r.line1 : `Meets every must-have: ${needs(f).join(', ')}.`,
    line2: ok ? (r.line2 || '') : 'Reason taken from the CV database fields.' };
});
const text = `*Top matches for:* ${q}\n\n` + out.map((c, n) =>
  `${n + 1}. *${c.name}* | Score: ${c.score}/100\n${c.line1}\n${c.line2}\nSource CV: ${c.cv_file}`).join('\n\n');
return [{ json: { found: true, candidates: out, text } }];

const needs = f => [
  ...(f.role ? [f.role.replace(/_/g, ' ')] : []),
  ...f.must_skills.map(s => s.min_years ? `${s.min_years}+ yrs ${s.name}` : s.name),
  ...f.must_languages,
  ...f.must_certifications,
  ...(f.must_flags.includes('supported_ceo') ? ['worked for a CEO or founder'] : []),
  ...(f.min_role_years ? [`${f.min_role_years}+ years in the role`] : []),
];

const f = $('Parse Filters').first().json;
return [{ json: { found: false, candidates: [],
  text: `No good match. Nobody in the database has all of: ${needs(f).join(', ') || 'no requirement was given'}.` } }];
